-- PostgreSQL baseline: complete application schema through legacy migration 027.
-- Legacy MySQL migration files remain archived; do not execute them on PostgreSQL.
CREATE EXTENSION IF NOT EXISTS unaccent;
CREATE EXTENSION IF NOT EXISTS citext;

CREATE FUNCTION touch_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN NEW.updated_at = CURRENT_TIMESTAMP; RETURN NEW; END;
$$;

CREATE TABLE "ai_call" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "upload_id" INTEGER,
  "document_id" INTEGER,
  "task" varchar(20) NOT NULL,
  "provider" varchar(20) NOT NULL,
  "model" varchar(100),
  "prompt_version" varchar(20),
  "input_tokens" INTEGER,
  "output_tokens" INTEGER,
  "latency_ms" INTEGER,
  "request_id" varchar(100),
  "status" varchar(10) NOT NULL,
  "error" varchar(500),
  "created_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL
 );

CREATE TABLE "certificate_type" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "code" CITEXT NOT NULL,
  "name_vi" varchar(200) NOT NULL,
  "name_en" varchar(200) NOT NULL,
  "issuing_authority" varchar(200),
  "validity_years" SMALLINT,
  "is_stcw" SMALLINT DEFAULT 1 NOT NULL CHECK ("is_stcw" IN (0, 1)),
  "category" VARCHAR(100) DEFAULT 'OTHER' NOT NULL CHECK ("category" IN ('STCW','VN','DOCUMENT','MEDICAL','PANAMA','OTHER')),
  "abbreviation" varchar(30),
  "required_for_ranks" JSONB,
  "created_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL
 );

CREATE TRIGGER "certificate_type_updated_at" BEFORE UPDATE ON "certificate_type" FOR EACH ROW EXECUTE FUNCTION touch_updated_at();

CREATE TABLE "contract_payroll" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "contract_id" INTEGER NOT NULL,
  "pay_period_year" SMALLINT NOT NULL,
  "pay_period_month" SMALLINT NOT NULL,
  "basic_wage_usd" decimal(10,2) NOT NULL,
  "overtime_hours" decimal(6,2),
  "overtime_amount_usd" decimal(10,2),
  "bonus_usd" decimal(10,2),
  "gross_usd" decimal(10,2) NOT NULL,
  "advance_deduction_usd" decimal(10,2),
  "insurance_deduction_usd" decimal(10,2),
  "net_usd" decimal(10,2) NOT NULL,
  "payment_date" DATE,
  "payment_method" varchar(30),
  "is_paid" SMALLINT DEFAULT 0 NOT NULL CHECK ("is_paid" IN (0, 1)),
  "notes" TEXT,
  "created_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL
 );

CREATE TABLE "contract_type" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "code" CITEXT NOT NULL,
  "name_vi" varchar(100) NOT NULL,
  "name_en" varchar(100),
