CREATE TABLE "training_course" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "course_code" varchar(50) NOT NULL,
  "course_type_id" INTEGER NOT NULL,
  "training_center_id" INTEGER NOT NULL,
  "name" varchar(200) NOT NULL,
  "start_date" DATE NOT NULL,
  "end_date" DATE,
  "location" varchar(200),
  "max_students" SMALLINT,
  "fee_vnd" decimal(12,2),
  "fee_usd" decimal(10,2),
  "instructor" varchar(200),
  "status" varchar(20) DEFAULT 'PLANNED' NOT NULL,
  "notes" TEXT,
  "created_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "deleted_at" TIMESTAMP WITHOUT TIME ZONE,
  "created_by" INTEGER,
  "updated_by" INTEGER
 );

CREATE TRIGGER "training_course_updated_at" BEFORE UPDATE ON "training_course" FOR EACH ROW EXECUTE FUNCTION touch_updated_at();

CREATE TABLE "training_enrollment" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "course_id" INTEGER NOT NULL,
  "seafarer_id" INTEGER NOT NULL,
  "enrollment_date" DATE NOT NULL,
  "rank_at_enrollment" INTEGER,
  "attendance_score" decimal(5,2),
  "attendance_max" SMALLINT DEFAULT 25,
  "process_score" decimal(5,2),
  "interview_score" decimal(5,2),
  "total_score" decimal(5,2),
  "grade" varchar(5),
  "result" varchar(20),
  "certificate_issued" SMALLINT DEFAULT 0 NOT NULL CHECK ("certificate_issued" IN (0, 1)),
  "certificate_id" INTEGER,
  "absence_reason" TEXT,
  "notes" TEXT,
  "created_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "deleted_at" TIMESTAMP WITHOUT TIME ZONE,
  "created_by" INTEGER,
  "updated_by" INTEGER,
  "status" varchar(20) DEFAULT 'ACTIVE' NOT NULL,
  "approved_by" INTEGER,
  "approved_at" TIMESTAMP WITHOUT TIME ZONE,
  "reject_reason" varchar(500),
  "referred_by_center_id" INTEGER
 );

CREATE TRIGGER "training_enrollment_updated_at" BEFORE UPDATE ON "training_enrollment" FOR EACH ROW EXECUTE FUNCTION touch_updated_at();

CREATE TABLE "user" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "email" CITEXT NOT NULL,
  "password_hash" varchar(255) NOT NULL,
  "role" varchar(30) NOT NULL,
  "verification_status" varchar(20) DEFAULT 'unverified' NOT NULL,
  "linked_entity_type" varchar(30),
  "linked_entity_id" INTEGER,
  "is_active" SMALLINT DEFAULT 1 NOT NULL CHECK ("is_active" IN (0, 1)),
  "verified_at" TIMESTAMP WITHOUT TIME ZONE,
  "last_login_at" TIMESTAMP WITHOUT TIME ZONE,
  "created_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "deleted_at" TIMESTAMP WITHOUT TIME ZONE
 );

CREATE TRIGGER "user_updated_at" BEFORE UPDATE ON "user" FOR EACH ROW EXECUTE FUNCTION touch_updated_at();

CREATE TABLE "vessel" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "imo_number" varchar(10),
  "mmsi" varchar(10),
  "call_sign" varchar(10),
  "vessel_name" varchar(150) NOT NULL,
  "vessel_name_prev" varchar(150),
  "vessel_type_id" INTEGER,
  "flag_country_id" INTEGER,
  "port_of_registry_id" INTEGER,
  "gross_tonnage" decimal(10,2),
  "net_tonnage" decimal(10,2),
  "deadweight" decimal(10,2),
  "length_overall" decimal(8,2),
  "year_built" SMALLINT,
  "classification_society" varchar(50),
  "ship_owner_id" INTEGER,
  "technical_manager" varchar(200),
  "commercial_manager" varchar(200),
  "status" varchar(30) DEFAULT 'IN_SERVICE' NOT NULL,
  "notes" TEXT,
  "created_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "deleted_at" TIMESTAMP WITHOUT TIME ZONE
 );

CREATE TRIGGER "vessel_updated_at" BEFORE UPDATE ON "vessel" FOR EACH ROW EXECUTE FUNCTION touch_updated_at();

CREATE TABLE "vessel_certificate_requirement" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "vessel_id" INTEGER NOT NULL,
  "rank_id" INTEGER NOT NULL,
  "certificate_type_id" INTEGER NOT NULL,
  "is_mandatory" SMALLINT DEFAULT 1 NOT NULL CHECK ("is_mandatory" IN (0, 1)),
  "notes" TEXT,
  "created_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL
 );

CREATE TABLE "vessel_type" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
